create extension if not exists pgcrypto;
create table if not exists organizations(id uuid primary key,name text not null);
create table if not exists users(id uuid primary key,organization_id uuid not null references organizations(id),display_name text not null);
create table if not exists plans(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),owner_id uuid not null references users(id),title text not null,horizon_start date,horizon_end date,status text not null default 'draft',version int not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists plan_members(plan_id uuid not null references plans(id) on delete cascade,user_id uuid not null references users(id),role text not null,primary key(plan_id,user_id));
create table if not exists plan_tasks(plan_id uuid not null references plans(id) on delete cascade,task_number int not null check(task_number between 1 and 14),status text not null default 'not_started',narrative jsonb not null default '{}',updated_at timestamptz not null default now(),primary key(plan_id,task_number));
create table if not exists records(id uuid primary key default gen_random_uuid(),plan_id uuid not null references plans(id) on delete cascade,task_number int check(task_number between 1 and 14),kind text not null,title text not null,data jsonb not null default '{}',created_by uuid not null references users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists records_lookup on records(plan_id,kind,created_at desc);
create table if not exists record_links(source_id uuid not null references records(id) on delete cascade,target_id uuid not null references records(id) on delete cascade,rationale text,primary key(source_id,target_id));
create table if not exists review_feedback(id uuid primary key default gen_random_uuid(),plan_id uuid not null references plans(id) on delete cascade,task_number int not null,finding text not null,outcome text not null,reviewer_id uuid not null references users(id),reviewer_name text not null,created_at timestamptz not null default now());
create table if not exists dependency_prompts(id uuid primary key default gen_random_uuid(),plan_id uuid not null references plans(id) on delete cascade,source_task int not null,affected_task int not null,reason text not null,resolved boolean not null default false,created_at timestamptz not null default now());
create table if not exists audit_events(id uuid primary key default gen_random_uuid(),plan_id uuid references plans(id) on delete cascade,actor_id uuid not null references users(id),entity_type text not null,entity_id uuid,action text not null,before_state jsonb,after_state jsonb,occurred_at timestamptz not null default now());
